import java.net.*;import java.util.*;
public class Main{static String scope(String s){try{InetAddress a=InetAddress.getByName(s);return(a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress())?"local/intranet":"public";}catch(Exception e){return"invalid";}}public static void main(String[]x)throws Exception{int p=Integer.parseInt(System.getenv().getOrDefault("NETWORK_API_PORT","8787"));Map<String,Object> m=new LinkedHashMap<>();m.put("schema","bizx.network.api.v1");m.put("implementation","java");m.put("port",p);m.put("endpoints",List.of("catalog","health","config","interfaces","classify","authorize","tcp-check"));System.out.println(m);System.out.println("scope 127.0.0.1 = "+scope("127.0.0.1"));try(Socket s=new Socket()){s.connect(new InetSocketAddress("127.0.0.1",p),1000);System.out.println("local API port reachable");}catch(Exception e){System.out.println("local API port not reachable (normal if server not running)");}}}
